-- One-time content release for the ten reviewed task replacements.
-- Applied by scripts/postgres-migrate.mjs before bootstrap seeding, including existing databases.
-- Frozen payload: do not regenerate this migration after it has been released.
-- Keep user progress/sessions, admin drafts, soft deletions and unrelated records intact.
CREATE TEMP TABLE olympus_task_release_20261026 (
  id TEXT PRIMARY KEY,
  data TEXT NOT NULL
) ON COMMIT DROP;

INSERT INTO olympus_task_release_20261026(id, data) VALUES
  ('info-5-02-task-1', $task_release_json${"id":"info-5-02-task-1","title":"Яблоки в корзине","topicId":"info-5-02","grade":5,"subject":"info","type":"number","prompt":"Семь школьников поровну делят 53 яблока. Целые яблоки, которые не удаётся разделить поровну, оставляют в корзине. Программа вычисляет, сколько яблок останется:\n```python\nn = 7\nk = 53\nprint(k % n)\n```\nКакое число она выведет?","answer":"4","solution":"Каждому можно дать по 7 яблок: для этого нужно 7 · 7 = 49 яблок. Если дать каждому по 8, понадобится 56 яблок, а столько нет. В корзине остаётся 53 − 49 = 4 яблока. Знак % как раз находит этот остаток. Программа выведет 4. Ответ: 4.","hint":"Найди самое большое количество яблок, которое можно раздать семи школьникам поровну. Сравни его с общим количеством.","points":1,"order":1,"kind":"tasks"}$task_release_json$),
  ('info-5-02-task-2', $task_release_json${"id":"info-5-02-task-2","title":"Ноль в разряде десятков","topicId":"info-5-02","grade":5,"subject":"info","type":"number","prompt":"Программа должна выделить цифру десятков числа 4706:\n```python\nn = 4706\nq = n // 10\nprint(q % 10)\n```\nКакое число она выведет? Учти, что цифра десятков и количество полных десятков – разные величины.","answer":"0","solution":"Деление 4706 на 10 нацело даёт q = 470: шесть единиц отброшены. В числе 470 последняя цифра – 0, потому что 470 = 47 · 10 + 0. Команда q % 10 выводит именно остаток 0. Это цифра десятков исходного числа, а не количество всех полных десятков. Ответ: 0.","hint":"Сначала убери цифру единиц делением нацело на 10. Затем найди последнюю цифру оставшегося числа.","points":1,"order":2,"kind":"tasks"}$task_release_json$),
  ('info-5-02-task-3', $task_release_json${"id":"info-5-02-task-3","title":"Парты для трёх кабинетов","topicId":"info-5-02","grade":5,"subject":"info","type":"code","prompt":"В трёх классах учатся a, b и c детей. У каждого класса свой кабинет. За одной партой могут сидеть один или два ребёнка; переносить парты между кабинетами во время урока нельзя. Найди наименьшее общее число парт, которого хватит всем трём классам.\n\nВходные данные\nТри целых числа a, b, c, каждое в отдельной строке. Ограничения: 1 ≤ a, b, c ≤ 1000.\n\nВыходные данные\nОдно целое число – необходимое количество парт.\n\nПример входных данных\n```\n19\n20\n23\n```\nПример выходных данных\n```\n32\n```","solution":"# В каждом кабинете размещаем детей парами. Деление x // 2 считает полные пары.\n# Если x нечётно, остаётся ребёнок и нужна ещё одна парта: (x + 1) // 2.\n# Число парт нельзя округлять после сложения детей: кабинеты отдельные.\n# Например, для 19, 20 и 23 детей нужны 10, 10 и 12 парт, всего 32.\n# Для одного ребёнка нужна одна парта; для 1000 детей – 500.\n# Читаем три числа и складываем три независимых результата. Цикл не нужен.\na = int(input())\nb = int(input())\nc = int(input())\nprint((a + 1) // 2 + (b + 1) // 2 + (c + 1) // 2)","hint":"Рассчитай число парт отдельно для каждого кабинета. Если после деления числа детей на 2 остаётся один ребёнок, ему тоже нужна парта.","tests":[{"input":"19\n20\n23\n","output":"32"},{"input":"1\n1\n1\n","output":"3"},{"input":"2\n2\n2\n","output":"3"},{"input":"1\n2\n3\n","output":"4"},{"input":"999\n999\n999\n","output":"1500"},{"input":"1000\n1000\n1000\n","output":"1500"},{"input":"1000\n1\n999\n","output":"1001"},{"input":"3\n3\n4\n","output":"6"}],"example":{"input":"19\n20\n23\n","output":"32"},"points":2,"order":3,"kind":"tasks"}$task_release_json$),
  ('info-5-02-task-4', $task_release_json${"id":"info-5-02-task-4","title":"Отметка на кольцевой дороге","topicId":"info-5-02","grade":5,"subject":"info","type":"code","prompt":"Кольцевая дорога имеет длину 109 км. Отметки на ней пронумерованы от 0 до 108 в положительном направлении. Велосипедист начинает движение на отметке 0. Его скорость v задана со знаком: положительная означает движение по возрастанию номеров, отрицательная – в обратную сторону. Через t часов он останавливается. Определи номер отметки остановки.\n\nВходные данные\nВ первой строке целое число v (−100 ≤ v ≤ 100), во второй – целое число t (0 ≤ t ≤ 1000).\n\nВыходные данные\nОдно целое число от 0 до 108 – номер отметки.\n\nПример входных данных\n```\n-20\n6\n```\nПример выходных данных\n```\n98\n```","solution":"# Пройденный путь со знаком равен v * t. Через каждые 109 км мы возвращаемся\n# на ту же отметку. Остаток при делении на 109 выбирает её номер от 0 до 108.\n# В Python остаток при положительном делителе неотрицателен, даже если путь отрицателен.\n# Например, при v = -20 и t = 6 путь равен -120; добавим 218 и получим отметку 98.\n# Если t = 0 или v = 0, остаёмся на отметке 0. Полный круг тоже даёт 0.\n# Здесь две команды ввода, умножение и остаток; перебор часов или километров не нужен.\nv = int(input())\nt = int(input())\nprint((v * t) % 109)","hint":"Полные круги не влияют на отметку. Для отрицательного пути добавляй длину круга, пока не попадёшь в диапазон от 0 до 108; подумай, какая операция Python делает это сразу.","tests":[{"input":"-20\n6\n","output":"98"},{"input":"0\n0\n","output":"0"},{"input":"100\n0\n","output":"0"},{"input":"0\n1000\n","output":"0"},{"input":"-1\n1\n","output":"108"},{"input":"1\n109\n","output":"0"},{"input":"100\n1000\n","output":"47"},{"input":"-100\n1000\n","output":"62"},{"input":"37\n3\n","output":"2"},{"input":"-37\n3\n","output":"107"}],"example":{"input":"-20\n6\n","output":"98"},"points":2,"order":4,"kind":"tasks"}$task_release_json$),
  ('info-5-02-task-5', $task_release_json${"id":"info-5-02-task-5","title":"В какой день улитка достигнет вершины","topicId":"info-5-02","grade":5,"subject":"info","type":"code","prompt":"Улитка начинает у основания вертикального шеста высотой h метров. Днём она поднимается на a метров, а ночью спускается на b метров. Достигнув вершины, улитка заканчивает путь и больше не спускается. Найди номер дня, в который она впервые достигнет вершины; первый день имеет номер 1.\n\nВходные данные\nТри целых числа h, a, b в отдельных строках. Ограничения: 1 ≤ h ≤ 10000, 1 ≤ a ≤ 10000, 0 ≤ b < a.\n\nВыходные данные\nОдно целое число – номер дня достижения вершины.\n\nПример входных данных\n```\n17\n6\n2\n```\nПример выходных данных\n```\n4\n```","solution":"# В последний день улитка поднимется ещё на a метров без последующего спуска.\n# Если h <= a, она доберётся уже в первый день. Иначе до последнего дня\n# нужно набрать не меньше h - a метров. Каждая полная пара день-ночь даёт a - b.\n# Делим h - a на a - b с округлением вверх и прибавляем последний день.\n# Например, h = 17, a = 6, b = 2: утром высоты 0, 4, 8, 12; днём 6, 10, 14, 18.\n# Вершина достигнута на четвёртый день: округление 11 / 4 вверх даёт 3, затем +1.\n# При b = 0 формула тоже верна; a > b гарантирует положительный ежедневный прирост.\n# Число действий не зависит от высоты шеста: вместо цикла используется формула.\nh = int(input())\na = int(input())\nb = int(input())\nif h <= a:\n    print(1)\nelse:\n    step = a - b\n    print((h - a + step - 1) // step + 1)","hint":"Выдели последний день: после него ночного спуска уже нет. Какую высоту нужно набрать за предыдущие полные дни и ночи?","tests":[{"input":"17\n6\n2\n","output":"4"},{"input":"1\n1\n0\n","output":"1"},{"input":"10\n10\n9\n","output":"1"},{"input":"3\n5\n4\n","output":"1"},{"input":"11\n6\n1\n","output":"2"},{"input":"12\n6\n1\n","output":"3"},{"input":"10000\n1\n0\n","output":"10000"},{"input":"10000\n9999\n9998\n","output":"2"},{"input":"10000\n2\n1\n","output":"9999"},{"input":"12\n4\n0\n","output":"3"},{"input":"13\n4\n0\n","output":"4"}],"example":{"input":"17\n6\n2\n","output":"4"},"points":3,"order":5,"kind":"tasks"}$task_release_json$),
  ('math-5-06-task-1', $task_release_json${"id":"math-5-06-task-1","title":"Три броска монеты","topicId":"math-5-06","grade":5,"subject":"math","type":"number","prompt":"Монету бросают три раза и записывают результаты по порядку: орёл или решка. Сколько разных записей может получиться? Например, орёл–решка–орёл и решка–орёл–орёл считаются разными записями.","answer":"8","solution":"Первый бросок даёт 2 варианта. После второго их 2 · 2 = 4. Каждый продолжается орлом или решкой: 4 · 2 = 8. Эти записи различаются хотя бы одним броском, поэтому повторов нет. Ответ: 8.","hint":"Сначала перечисли записи для двух бросков. Каждую можно продолжить двумя способами.","points":1,"order":1,"kind":"tasks"}$task_release_json$),
  ('math-5-06-task-2', $task_release_json${"id":"math-5-06-task-2","title":"Капитан и заместитель","topicId":"math-5-06","grade":5,"subject":"math","type":"number","prompt":"В команде 11 футболистов. Нужно выбрать капитана и его заместителя, причём это должны быть разные люди. Сколько существует вариантов распределения этих двух должностей?","answer":"110","solution":"Капитаном может стать любой из 11 футболистов. После его выбора остаётся 10 кандидатов в заместители. Для каждого капитана получаем 10 вариантов, всего 11 · 10 = 110. Перестановка людей меняет должности, значит, создаёт другой вариант. Ответ: 110.","hint":"Выбери капитана. Сколько футболистов после этого остаётся для второй должности?","points":1,"order":2,"kind":"tasks"}$task_release_json$),
  ('math-5-06-task-3', $task_release_json${"id":"math-5-06-task-3","title":"Пять разных шариков","topicId":"math-5-06","grade":5,"subject":"math","type":"number","prompt":"Пять ёлок стоят на разных местах. Есть пять шариков разных цветов. На каждую ёлку нужно повесить ровно один шарик и использовать все шарики. Сколькими способами можно это сделать?","answer":"120","solution":"Для первой ёлки есть 5 шариков, для второй остаётся 4, затем 3, 2 и 1. Поэтому вариантов 5 · 4 · 3 · 2 · 1 = 120. Каждое размещение соответствует одной последовательности выборов, так что ничего не пропущено и не посчитано повторно. Ответ: 120.","hint":"Рассмотри ёлки слева направо. После выбора шарика для первой ёлки сколько шариков останется для следующей?","points":2,"order":3,"kind":"tasks"}$task_release_json$),
  ('math-5-06-task-4', $task_release_json${"id":"math-5-06-task-4","title":"Партии без повторов","topicId":"math-5-06","grade":5,"subject":"math","type":"number","prompt":"Шесть шахматистов проводят турнир. Каждая пара участников играет ровно одну партию. Сколько партий будет сыграно всего?","answer":"15","solution":"Первый играет с пятью участниками. Среди оставшихся второй образует ещё 4 новые пары, третий – 3, четвёртый – 2, пятый – 1. Получаем 5 + 4 + 3 + 2 + 1 = 15. Каждая пара учтена один раз – по тому, кто стоит раньше в этом перечислении. Ответ: 15.","hint":"Сначала посчитай партии первого участника с остальными. Затем не включай его в следующие пары, чтобы не повторять уже учтённые партии.","points":2,"order":4,"kind":"tasks"}$task_release_json$),
  ('math-5-06-task-5', $task_release_json${"id":"math-5-06-task-5","title":"Дороги посчитаны дважды","topicId":"math-5-06","grade":5,"subject":"math","type":"number","prompt":"В стране 100 городов. Каждый город соединён дорогами ровно с четырьмя другими городами. Каждая дорога соединяет два города; дорог, ведущих из города обратно в него же, нет. Сколько всего дорог в стране?","answer":"200","solution":"Если сложить количества дорог у всех городов, получится 100 · 4 = 400. Но дорога соединяет два города, поэтому вошла в эту сумму дважды. Настоящее количество дорог вдвое меньше: 400 : 2 = 200. Ответ: 200.","hint":"Поставь у каждого города по отметке за каждую выходящую из него дорогу. Сколько отметок получит одна дорога со стороны двух её концов?","points":3,"order":5,"kind":"tasks"}$task_release_json$);

DO $release_guard$
BEGIN
  IF EXISTS (
    SELECT 1 FROM records r JOIN olympus_task_release_20261026 t ON t.id = r.id
    WHERE r.kind <> 'tasks'
  ) THEN
    RAISE EXCEPTION 'Task release 2026-10-26: an id belongs to another record kind';
  END IF;
END;
$release_guard$;

-- Store the published version before replacing it. An already current row needs no revision.
INSERT INTO revisions(id, record_id, data, created)
SELECT gen_random_uuid()::text, r.id, r.data,
       floor(extract(epoch FROM statement_timestamp()) * 1000)::bigint
FROM records r JOIN olympus_task_release_20261026 t ON t.id = r.id
WHERE r.deleted = 0 AND r.data::jsonb IS DISTINCT FROM t.data::jsonb;

UPDATE records r
SET data = t.data,
    updated = GREATEST(r.updated + 1, floor(extract(epoch FROM statement_timestamp()) * 1000)::bigint)
FROM olympus_task_release_20261026 t
WHERE r.id = t.id AND r.deleted = 0 AND r.data::jsonb IS DISTINCT FROM t.data::jsonb;

-- A missing task is created only when its topic already exists. In an empty database bootstrap
-- will populate the complete current bundle after migrations, preserving the normal first start.
INSERT INTO records(id, kind, data, draft, updated, deleted)
SELECT t.id, 'tasks', t.data, NULL,
       floor(extract(epoch FROM statement_timestamp()) * 1000)::bigint, 0
FROM olympus_task_release_20261026 t
WHERE NOT EXISTS (SELECT 1 FROM records r WHERE r.id = t.id)
  AND EXISTS (
    SELECT 1 FROM records topic
    WHERE topic.id = t.data::jsonb->>'topicId' AND topic.kind = 'topics' AND topic.deleted = 0
  );

-- Keep per-record seed hashes consistent if the server explicitly uses SEED_MODE=sync.
-- Leave the bundle marker and hashes of deleted or absent rows alone.
INSERT INTO imports(id, hash)
SELECT t.id, encode(sha256(convert_to(t.data, 'UTF8')), 'hex')
FROM olympus_task_release_20261026 t JOIN records r ON r.id = t.id
WHERE r.deleted = 0 AND r.data::jsonb = t.data::jsonb
ON CONFLICT(id) DO UPDATE SET hash = excluded.hash;
